<div class="page-heading"><div><span class="eyebrow"><?= e(t('KNOW WHAT IS STILL DUE')) ?></span><h1><?= e(t('Payables & receivables')) ?></h1><p><?= e(t('A clear list of who owes you, and who you need to pay.')) ?></p></div><a class="button primary" href="<?= url('debts/new') ?>"><?= icon('plus') ?><?= e(t('New unpaid balance')) ?></a></div>
<section class="metrics two-metrics"><div class="metric"><div><span class="metric-label"><?= e(t('To receive')) ?></span><strong class="positive"><?= e(money($totals['receivable'])) ?></strong><small><?= e(t('Outstanding · matching filters')) ?></small></div><span class="metric-icon success"><?= icon('arrow-down') ?></span></div><div class="metric"><div><span class="metric-label"><?= e(t('To pay')) ?></span><strong class="negative"><?= e(money($totals['payable'])) ?></strong><small><?= e(t('Outstanding · matching filters')) ?></small></div><span class="metric-icon danger"><?= icon('arrow-up') ?></span></div></section>
<section class="panel ledger-panel"><form method="get" class="filter-bar"><label class="field search-field"><span><?= e(t('Search')) ?></span><input name="q" type="search" value="<?= e($filters['q']) ?>" placeholder="<?= e(t('Notes or person’s name')) ?>"></label><label class="field"><span><?= e(t('Business / personal')) ?></span><select name="business_id"><option value=""><?= e(t('All businesses & personal')) ?></option><?php foreach ($businesses as $business): ?><option value="<?= $business['id'] ?>"<?= selected($filters['business_id'],$business['id']) ?>><?= e($business['name']) ?></option><?php endforeach ?></select></label><label class="field"><span><?= e(t('Person')) ?></span><select name="person_id"><option value=""><?= e(t('All people')) ?></option><?php foreach ($people as $person): ?><option value="<?= $person['id'] ?>"<?= selected($filters['person_id'],$person['id']) ?>><?= e($person['name']) ?></option><?php endforeach ?></select></label><label class="field"><span><?= e(t('Direction')) ?></span><select name="direction"><option value=""><?= e(t('Both directions')) ?></option><?php foreach (['receivable'=>'To receive','payable'=>'To pay'] as $key=>$label): ?><option value="<?= $key ?>"<?= selected($filters['direction'],$key) ?>><?= e(t($label)) ?></option><?php endforeach ?></select></label><label class="field"><span><?= e(t('Status')) ?></span><select name="status"><?php foreach ([''=>'All statuses','open'=>'Outstanding','overdue'=>'Overdue','settled'=>'Settled'] as $key=>$label): ?><option value="<?= $key ?>"<?= selected($filters['status'],$key) ?>><?= e(t($label)) ?></option><?php endforeach ?></select></label><div class="filter-actions"><button class="button"><?= e(t('Apply filters')) ?></button><a class="text-button" href="<?= url('debts') ?>"><?= e(t('Reset')) ?></a></div></form>
<div class="list-summary"><span><?= $totalRows ?> <?= e(t('records')) ?></span><span><?= e(t('Amounts in MMK')) ?></span></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Person / business')) ?></th><th><?= e(t('Direction')) ?></th><th><?= e(t('Due date')) ?></th><th class="number"><?= e(t('Original amount')) ?></th><th class="number"><?= e(t('Paid / received')) ?></th><th class="number"><?= e(t('Remaining')) ?></th><th><?= e(t('Status')) ?></th><th class="actions-col"><?= e(t('Actions')) ?></th></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr><td><strong><?= e($row['person_name']) ?></strong><small><?= e($row['business_name']) ?></small></td><td><?= status_badge($row['direction']) ?></td><td><?= e($row['due_date'] ?: '—') ?></td><td class="number"><?= number_format((int) $row['amount']) ?></td><td class="number"><?= number_format((int) $row['paid']) ?></td><td class="number amount"><?= number_format((int) $row['remaining']) ?></td><td><?= status_badge(debt_status($row)) ?></td><td class="actions-col"><a class="text-button" href="<?= url('debts/' . $row['id']) ?>"><?= e(t('View / pay')) ?> →</a></td></tr><?php endforeach ?>
<?php if (!$rows): ?><tr><td colspan="8"><div class="empty-state"><?= icon('debts') ?><strong><?= e(t('No matching unpaid balances')) ?></strong><span><?= e(t('Add a balance or change the filters to see settled records.')) ?></span></div></td></tr><?php endif ?></tbody></table></div><?php require BASE_PATH . '/app/Views/partials/pagination.php'; ?></section>
